import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";

export default function ListarUsuarios() {
  const [usuarios, setUsuarios] = useState([]);
  const navigate = useNavigate();

  useEffect(() => {
    axios.get("http://localhost:3001/usuarios")
      .then(res => setUsuarios(res.data))
      .catch(err => console.error("Erro ao carregar usuários:", err));
  }, []);

  const excluirUsuario = async (id) => {
    const confirmar = window.confirm("Deseja realmente excluir?");
    if (!confirmar) return;

    try {
      await axios.delete(`http://localhost:3001/usuarios/${id}`);
      setUsuarios((prev) => prev.filter(user => user.id !== id));
    } catch (err) {
      console.error("Erro ao excluir:", err);
      alert("Erro ao excluir.");
    }
  };

  return (
    <div className="container mt-5">
      <div className="d-flex justify-content-end mb-4">
        <button className="btn btn-success" onClick={() => navigate("/cadastrar")}>
          Cadastrar Novo
        </button>
      </div>

      <div className="table-responsive d-flex justify-content-center">
        <table className="table table-bordered text-center shadow-lg" style={{ maxWidth: 600 }}>
          <thead className="table-dark">
            <tr>
              <th>Nome</th>
              <th>Foto</th>
              <th>Ações</th>
            </tr>
          </thead>
          <tbody>
            {usuarios.map((user) => (
              <tr key={user.id}>
                <td>{user.nome}</td>
                <td>
                  {user.imagem ? (
                    <img
                      src={`http://localhost:3001${user.imagem}`}
                      alt="Foto"
                      style={{ width: 40, height: 40, borderRadius: "50%", objectFit: "cover" }}
                    />
                  ) : (
                    "-"
                  )}
                </td>
                <td>
                  <button className="btn btn-outline-info btn-sm me-2" onClick={() => navigate(`/usuarios/${user.id}`)}>
                    <i className="bi bi-eye"></i>
                  </button>
                  <button className="btn btn-outline-warning btn-sm me-2" onClick={() => navigate(`/editar/${user.id}`)}>
                    <i className="bi bi-pencil"></i>
                  </button>
                  <button className="btn btn-outline-danger btn-sm" onClick={() => excluirUsuario(user.id)}>
                    <i className="bi bi-trash"></i>
                  </button>
                </td>
              </tr>
            ))}
            {usuarios.length === 0 && (
              <tr>
                <td colSpan="3">Nenhum usuário encontrado.</td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}
